      SUBROUTINE EXTENTCC     CONSTRAINT ON BEAM SIZECC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM10A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10D.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'RCP.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'SI.CIN'      INCLUDE 'SVP.CIN'CC     LOCAL VARIABLESC      LOGICAL  LOGIC      REAL  AS(NPVAR+1), CAD(NPVAR+1), CADS(NPVAR+1), RSV(6,NPVAR)CC---------------------------------------------------------------      J = JCON      IF (.NOT. RECENT) CALL BEAM      SIJJ = SIT(J,J)      IF (SIJJ .LT. 0.0) THEN        IF (ABS(SIJJ) .LT. 1.0E-6) THEN          SIJJ = 0.0        ELSE          SOJJ = SIJJ/UBEAM(J)**2          WRITE (NOUT,1000) J, J, SOJJ 1000     FORMAT (1H ,'BEAM MATRIX ELEMENT SI(',I1,',',I1,') = ',     1            1PE12.4,/,1H ,'MUST BE POSITIVE, PROBABLY A TYPO')          FLUSHL = .TRUE.          GO TO 300        ENDIF      ENDIF      SSJJ = SQRT(SIJJ)      COC = SSJJ/UBEAM(J)      IF (NV3 .GE. 1) CW = 1.0/SD**2      IF (DE0 .EQ. 0.0 .AND. TYPE .EQ. 10) GO TO 200      IF (NV3 .LT. 1) GO TO 50      A(1) = DE0 - COC      CALL CLI(LOGIC)      IF (LOGIC) RETURNC      IF (NV1 .LT. 1) GO TO 50      DO 40 N = 1, NV1, 1      IF (R2P) GO TO 10      IF (.NOT. SVP(N)) GO TO 40      SVJJ = SV(J,J,N)      GO TO 30   10 SVJJ = 0.0      IF (SVP(N)) THEN        DO 11 L1 = 1, 6        DO 11 L2 = 1, 6        SVJJ = SVJJ +  RC2(J,L1)*SV(L1,L2,N)*RC2(J,L2)   11   CONTINUE      ENDIF      IF (R2VP(N)) THEN        DO 21 L1 = 1, 6        DO 21 L2 = 1, 6        SVJJ = SVJJ + 2.0*R2V(J,L1,N)*SI(L1,L2)*RC2(J,L2)   21   CONTINUE      ENDIF   30 A(N+1) = 0.5*SVJJ/(SSJJ*UBEAM(J))      CAD(N+1) = CW*A(N+1)*A(N+1)   40 CONTINUEC   50 IF (NV1 .LT. 1) GO TO 150      IF (.NOT. (R2P .OR. RCP)) GO TO 150      DO 90 N = 1, NV1      SVJJ = 0.0      IF (R2VP(N)) THEN        DO 65 L1 = 1, 6        DO 65 L2 = 1, 6        SVJJ = SVJJ + R2V(J,L1,N)*SI(L1,L2)*R2V(J,L2,N)   65   CONTINUE      ENDIFC   70 IF (R2VP(N) .AND. SVP(N)) THEN        DO 75 L1 = 1, 6        DO 75 L2 = 1, 6        SVJJ = SVJJ + R2V(J,L1,N)*SV(L1,L2,N)*RC2(J,L2)     1       + RC2(J,L1)*SV(L1,L2,N)*R2V(J,L2,N)   75   CONTINUE      ENDIFC   80 SVJJ = 0.5*SVJJ/(SSJJ*UBEAM(J))      SVJJ = SVJJ - A(N+1)*A(N+1)*UBEAM(J)/SSJJ      AS(N+1) = SVJJ      CADS(N+1) = A(1)*CW*AS(N+1)      IF (CAD(N+1) .LT. CADS(N+1)) THEN        DV = SIGN(SQRT(2.0*A(1)/AS(N+1)),A(N+1))        A(N+1) = A(N+1) + DV*AS(N+1)      ENDIF   90 CONTINUEC  150 CALL GATHER      RETURNCC     MINIMIZATION OF BEAM SIZEC  200 CA(1,1) = CA(1,1) + COC**2*CW      IF (NV3 .LT. 1) RETURNC      IF (NV1 .LT. 1) GO TO 250      DO 220 N = 1, NV1      DO 220 L1 = 1, 6      SS = 0.0      DO 215 L2 = 1, 6      SS = SS + R2V(J,L2,N)*SI(L1,L2)  215 CONTINUE      RSV(L1,N) = SS  220 CONTINUEC      DO 230 N = 1, NV1      SS = 0.0      DO 225 K = 1, 6      SS = SS + RC2(J,K)*RSV(K,N)  225 CONTINUE      CA(N+1,1) = CA(N+1,1) - SS*CW/UBEAM(J)**2  230 CONTINUEC      DO 240 N1 = 1, NV1      DO 240 N2 = 1, N1      SS = 0.0      DO 235 K = 1, 6      SS = SS + R2V(J,K,N1)*RSV(K,N2)  235 CONTINUE      CA(N1+1,N2+1) = CA(N1+1,N2+1) + SS*CW/UBEAM(J)**2  240 CONTINUE  250 CONTINUEC      IF (NORD3 .GE. 2) CALL CONSECC  300 RETURN      END